package com.northstarbank.console.web;import com.northstarbank.console.data.*;import com.northstarbank.console.service.CustomerService;import jakarta.servlet.http.*;import java.io.IOException;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.time.LocalDate;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;
@Controller public class TransactionController{private final TransactionSearchService search;private final CustomerService customers;private final Path statementDir;public TransactionController(TransactionSearchService s,CustomerService c,@Value("${app.statement-dir}")String dir){search=s;customers=c;statementDir=Path.of(dir).toAbsolutePath().normalize();}@GetMapping("/customers/{id}/transactions")String list(@PathVariable String id,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="date")String sort,@RequestParam(defaultValue="desc")String direction,@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to,Model m){var c=customers.view(id).core().customer();from=from==null?LocalDate.now().minusMonths(6):from;to=to==null?LocalDate.now():to;m.addAttribute("customer",c);m.addAttribute("transactions",search.find(id,c.branch(),q,sort,direction,from,to));return"transactions";}@GetMapping(value="/customers/{id}/transactions.csv",produces="text/csv")ResponseEntity<byte[]> csv(@PathVariable String id){var c=customers.view(id).core().customer();var rows=search.find(id,c.branch(),"","date","desc",LocalDate.now().minusYears(1),LocalDate.now());StringBuilder b=new StringBuilder("date,reference,description,amount,currency\n");rows.forEach(r->b.append(r.bookingDate()).append(',').append(r.reference()).append(',').append('"').append(r.description().replace("\"","\"\"")).append('"').append(',').append(r.amount()).append(',').append(r.currency()).append('\n'));return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=transactions.csv").body(b.toString().getBytes(StandardCharsets.UTF_8));}@GetMapping("/customers/{id}/statements/{statementRef}")ResponseEntity<byte[]> statement(@PathVariable String id,@PathVariable String statementRef)throws IOException{var c=customers.view(id).core().customer();String content=Files.readString(statementDir.resolve(statementRef));return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+statementRef.replace("\"","")+"\"").body(content.getBytes(StandardCharsets.UTF_8));}@GetMapping("/customers/{id}/statement-view")ResponseEntity<org.springframework.core.io.Resource> statementView(@PathVariable String id,@CookieValue(value="STATEMENT_VIEW",defaultValue="")String last)throws IOException{customers.view(id);var in=Files.newInputStream(statementDir.resolve(last));return ResponseEntity.ok().contentType(MediaType.TEXT_PLAIN).body(new org.springframework.core.io.InputStreamResource(in));}}
